static int loadProjection(projectionObj *p)
{
  int i=0;

  p->gt.need_geotransform = MS_FALSE;

  if ( p->proj != NULL ) {
    msSetError(MS_MISCERR, "Projection is already initialized. Multiple projection definitions are not allowed in this object. (line %d)",
