{
#if PROJ_VERSION_MAJOR >= 6
  proj_destroy(p->proj);
  p->proj = NULL;
  msProjectionContextUnref(p->proj_ctx);
  p->proj_ctx = NULL;
#else
  if(p->proj) {
    pj_free(p->proj);
    p->proj = NULL;
  }
